---@meta ermod
-- Type stubs for the ermod Lua SDK. Generated by the engine (`ermod-engine dev stubs`); do not edit.
-- Point your Lua language server at the directory holding this file
-- (e.g. .luarc.json: { "workspace.library": ["path/to/stubs"] }).

---@alias ermod.run_at "launch"|"events"
---@alias ermod.permission "log"|"hooks"|"params"|"perf"|"store"|"ui"|"screen"|"watch"|"rules"|"bosses"|"trace"|"coop"|"player"

---The `sdk` table a mod's entry point receives. Only the modules the
---manifest's `permissions` list are present; the rest are nil.
---@class ermod.sdk
---@field log ermod.sdk.log?
---@field hooks ermod.sdk.hooks?
---@field params ermod.sdk.params?
---@field perf ermod.sdk.perf?
---@field store ermod.sdk.store?
---@field ui ermod.sdk.ui?
---@field screen ermod.sdk.screen?
---@field watch ermod.sdk.watch?
---@field rules ermod.sdk.rules? # present with the "rules" permission
---@field bosses ermod.sdk.bosses? # present with the "bosses" permission
---@field trace ermod.sdk.trace? # present with the "trace" permission
---@field coop ermod.sdk.coop? # present with the "coop" permission
---@field player ermod.sdk.player? # present with the "player" permission
---@field items ermod.sdk.items # every item, spell, skill and class by row id; always present

---The table a mod script returns.
---@class ermod.mod
---@field name string
---@field version string
---@field run_at ermod.run_at
---@field permissions ermod.permission[]
---@field mods string[]? # makes this mod a pack: the manifest names of its members, which take precedence over standalone mods
---@field on_launch fun(sdk: ermod.sdk)? # run_at = "launch": runs once at load (and on hot-reload)
---@field setup fun(sdk: ermod.sdk)?     # run_at = "events": registers handlers with sdk.hooks

---@class ermod.sdk.log
local log = {}

---Write an info line to the engine log, tagged with this mod's name.
---@param msg string
function log.info(msg) end

---Write a warning line.
---@param msg string
function log.warn(msg) end

---Write an error line.
---@param msg string
function log.error(msg) end

---@class ermod.sdk.hooks
local hooks = {}

---The events a mod can subscribe to. Each value is the event's own
---name. Indexing an event that does not exist is an error, not nil.
---@enum ermod.event
hooks.event = {
  ---A frame is about to be presented; handlers must be cheap. Payload: {}
  on_present = "on_present",
  ---The player gained runes. Payload: { amount = integer }
  on_rune_gain = "on_rune_gain",
  ---The player died. Payload: { deaths = integer }, the character's lifetime death count including this one (the game's own counter; sdk.watch.stat.deaths reads it any time)
  on_death = "on_death",
  ---A boss died and the game recorded its defeat. Payload: { id = integer (sdk.bosses.id), flag = integer, kind = string }
  on_boss_defeated = "on_boss_defeated",
  ---The player entered an evergaol, opened by hand or by bosses.open. Payload: { id = integer (sdk.bosses.id) }
  on_evergaol_entered = "on_evergaol_entered",
}

---@class ermod.event.payload
---@field amount integer? # on_rune_gain only
---@field id integer? # on_boss_defeated only: the boss's row id (sdk.bosses.id)
---@field flag integer? # on_boss_defeated only: its defeat flag
---@field kind string? # on_boss_defeated only: its kind (sdk.bosses.kind)
---@field deaths integer? # on_death only: the character's lifetime death count, including this death

---Subscribe to a named engine event. Unknown names are an error at
---subscribe time. Handlers run under the instruction budget; a handler
---that errors strikes the mod (three strikes disables it), one that
---exhausts its budget disables it on the spot.
---@param event ermod.event
---@param handler fun(ev: ermod.event.payload)
function hooks.on(event, handler) end

---A live param row. Fields are the paramdef's field names, read and
---written by name; `id` is the row id unless the paramdef has such a
---field. Writes land in game memory at once and last for the process.
---@class ermod.params.row
---@field id integer
---@field [string] number

---@class ermod.sdk.params
local params = {}

---The param files a mod can name: those with a vendored paramdef. Each
---value is the file's own name. Indexing a file that does not exist is
---an error, not nil.
---@enum ermod.param_file
params.file = {
  ---`CHARACTER_INIT_PARAM` rows, 320 bytes each.
  CharaInitParam = "CharaInitParam",
  ---`ITEMLOT_PARAM_ST` rows, 152 bytes each.
  ItemLotParam_enemy = "ItemLotParam_enemy",
  ---`ITEMLOT_PARAM_ST` rows, 152 bytes each.
  ItemLotParam_map = "ItemLotParam_map",
  ---`EQUIP_PARAM_WEAPON_ST` rows, 664 bytes each.
  EquipParamWeapon = "EquipParamWeapon",
  ---`EQUIP_PARAM_PROTECTOR_ST` rows, 416 bytes each.
  EquipParamProtector = "EquipParamProtector",
  ---`EQUIP_PARAM_GOODS_ST` rows, 176 bytes each.
  EquipParamGoods = "EquipParamGoods",
  ---`NPC_PARAM_ST` rows, 736 bytes each.
  NpcParam = "NpcParam",
  ---`SP_EFFECT_PARAM_ST` rows, 912 bytes each.
  SpEffectParam = "SpEffectParam",
}

---One row of a param file by id, or nil if there is no such row.
---Errors if the file is unknown, not loaded yet, or the live table
---does not match the vendored paramdef.
---@param file ermod.param_file # e.g. params.file.CharaInitParam
---@param id integer
---@return ermod.params.row?
function params.row(file, id) end

---Iterate every row of a param file in table order.
---@param file ermod.param_file
---@return fun(): ermod.params.row?
function params.rows(file) end

