watch.stat = {
  ---Times the current character has died.
  deaths = "deaths",
  ---Runes held (not the ones lying where the character last died).
  runes = "runes",
  ---Rune level.
  level = "level",
  ---Vigor attribute.
  vigor = "vigor",
  ---Mind attribute.
  mind = "mind",
  ---Endurance attribute.
  endurance = "endurance",
  ---Strength attribute.
  strength = "strength",
  ---Dexterity attribute.
  dexterity = "dexterity",
  ---Intelligence attribute.
  intelligence = "intelligence",
  ---Faith attribute.
  faith = "faith",
  ---Arcane attribute.
  arcane = "arcane",
  ---Current HP of the local player.
  hp = "hp",
  ---Maximum HP of the local player (moves with vigor, buffs and talismans).
  hp_max = "hp_max",
  ---Whole metres to the nearest other player in a co-op session; unreadable (nil) when there is none.
  coop_distance = "coop_distance",
}

---@class ermod.watch.change
---@field stat ermod.stat
---@field old integer
---@field new integer
---@field delta integer # new - old

---Call `handler` on every frame `stat` changes. Nothing fires for the
---value a save loads with, nor outside a loaded world. Unknown names are
---an error at subscribe time. Handlers run under the instruction budget
---and the same strike policy as `hooks.on`.
---@param stat ermod.stat
---@param handler fun(change: ermod.watch.change)
function watch.on(stat, handler) end

---The current value of `stat`, or nil when it cannot be read (no world
---loaded, or the player not yet placed).
---@param stat ermod.stat
---@return integer?
function watch.get(stat) end

---Engine-wide game rules. Present when the manifest holds the "rules"
---permission. Every rule is readable and settable, from the entry
---point only. A mod pack's value wins over a standalone mod's.
---@class ermod.sdk.rules
---@field boss_spectate boolean # fog-wall bosses: a dead peer watches a survivor instead of respawning (default true)
---@field spirit_summon_anywhere boolean # spirit ashes work anywhere, not only at a Rebirth Monument; one at a time, and it stays with the player (default false)

---Every boss the game pays a clear for, base game and DLC, from the
---regulation's GameAreaParam. Present with the "bosses" permission.
---A revive clears the boss's defeat flag; the boss is back the next
---time its map loads (rest at a grace, warp, or die).
---@class ermod.sdk.bosses
---@field all ermod.boss[] # every boss, in GameAreaParam row order
---@field id ermod.bosses.id # every boss by name: sdk.bosses.id.margit_the_fell_omen == 10000850
local bosses = {}

---@class ermod.boss
---@field id integer # GameAreaParam row id (what sdk.bosses.id.<key> is)
---@field key string # its sdk.bosses.id key, e.g. "margit_the_fell_omen" ("boss_<row>" where unresolved)
---@field display_name string # its one name, e.g. "Margit, the Fell Omen"; "" where unresolved
---@field name_measured boolean # display_name was read off the boss itself in the game (its model's names); false where it is assigned by row and not yet checked live
---@field name string # "c<model>: <every name the game files under its model>"; "" where not measured
---@field npc_param integer? # its NpcParam row (stats); nil where not measured
---@field flag integer # the defeat flag a revive clears
---@field map string # the boss's map, e.g. "m10_00_00_00"
---@field dlc boolean # Shadow of the Erdtree
---@field runes integer # runes paid on the kill (solo)
---@field marker ermod.vec3 # GameAreaParam's marker near the arena (not the player's coordinate frame)
---@field idle_pos ermod.vec3? # where the boss waits before its fight (maybe outside the arena), in the player's frame near it; nil if not measured
---@field arena ermod.vec3? # where the player stood when a recorded fight began (inside the fog); nil if none recorded
---@field fight_pos ermod.vec3? # where the boss fought in that fight (its mean position near the player); nil if none recorded
---@field fight_radius number? # how far it ranged in that fight, metres; nil if none recorded
---@field drops string[] # what the game awarded when it died, "count x name" (empty if not measured)
---@field drop_lots integer[] # the item lots behind `drops` (negative: ItemLotParam_enemy)
---@field bodies { entity: integer, hp_max: integer }[] # the encounter's bodies seen live (partners, phases, waves)
---@field hp_max integer? # measured max HP; nil if not measured
---@field kind ermod.bosses.kind # "evergaol", "minor_erdtree", "field" (open world) or "arena" (a dungeon's boss room)
---@field phases integer? # kills the game needed before it recorded the defeat (each body or phase that comes back); nil if not measured
---@field evergaol string? # the evergaol's name, for an evergaol boss
---@field grace integer? # the grace `bosses.warp` travels to (entity id); nil if it has none
---@field spawns { phase: string, entity: integer, map: string, pos: ermod.vec3 }[] # where the boss was: "idle" (before the fight), "fight" (when it started), "kill1".. (each body killed; a second phase shows as kill2); pos in the frame the player is in near it, map the boss's map block (hex). Empty where not recorded.
---@field can_open boolean? # evergaol bosses: true when the SDK can open its evergaol (`bosses.open`, `warp(id, { open = true })`): its pad has been recorded

---@class ermod.vec3
---@field x number
---@field y number
---@field z number

---@class ermod.boss_state
---@field loaded boolean # a body of the encounter is in the world now
---@field alive boolean # loaded, and any body alive (a wave fight like Fia's Champions has several); false when not loaded
---@field defeated boolean? # the game's defeat record: true, it stays dead at its map's next load; false, it is there. nil outside a world
---@field hp integer? # the row's own character (or the first body when it is not loaded); nil when not loaded
---@field hp_max integer? # nil when not loaded
---@field pos ermod.vec3? # live position, in the player's frame near it; nil when not loaded
---@field bodies_alive integer # loaded bodies of the encounter that are alive
---@field bodies ermod.boss_body[] # every loaded body: entity ids row .. row+9 (empty when not loaded)

---@class ermod.boss_body
---@field entity integer
---@field hp integer
---@field hp_max integer
---@field pos ermod.vec3

---@enum ermod.bosses.kind
bosses.kind = { arena = "arena", field = "field", minor_erdtree = "minor_erdtree", evergaol = "evergaol" }

---Travel to the boss's grace, then, once the boss has loaded: beside the boss; for an
---evergaol boss with `can_open`, on its pad, and with `open = true` the evergaol opened too.
---@param id integer # row id or defeat flag
---@param opts { open: boolean? }?
---@return boolean queued
function bosses.warp(id, opts) end

---Open the boss's evergaol for the player (it must be near): the pad, "Enter evergaol?" YES,
---then a step towards the boss. The game window must have focus. Errors unless `can_open`.
---@param id integer
---@return boolean queued
function bosses.open(id) end

---Start the boss's fight: its AI's wake bit, what a fog or an evergaol turns on.
---@param id integer
---@param entity integer? # a body of the encounter; the row's own by default
---@return boolean queued
function bosses.wake(id, entity) end

---Kill a live body through the game's own death routine; the game records the defeat.
---A boss with more `phases` needs a kill for each.
---@param id integer
---@param entity integer?
---@return boolean queued
function bosses.kill(id, entity) end

---Bring the fight back as new (the defeat flag, and an evergaol's own state); lands when the map next loads.
---@param id integer
---@return integer writes # flag writes queued
function bosses.reset(id) end

---The boss's state, always: loaded, alive and defeated; HP and position while loaded (refreshed every 30 frames).
---@param id integer # row id or defeat flag
---@return ermod.boss_state
function bosses.state(id) end

---The player's live position, or nil outside a world.
---@return ermod.vec3?
function bosses.player_pos() end

---True while a boss fight is under way: the player passed a boss's fog and it has not died.
---@return boolean
function bosses.in_fight() end

---Where the player stood when the current fight began (inside the fog), or nil outside a fight.
---@return ermod.vec3?
function bosses.fight_entry() end

---@class ermod.boss_stats
---@field npc_param integer # the boss's NpcParam row; any field: bosses.stat / sdk.params
---@field hp integer # NpcParam hp (the base before area scaling)
---@field damage_taken { neutral: number, slash: number, blow: number, thrust: number, magic: number, fire: number, thunder: number, dark: number } # HP damage multiplier per damage type: < 1 resists that type, > 1 weak to it
---@field status_resist { poison: integer, disease: integer, blood: integer, curse: integer, sleep: integer, madness: integer } # status build-up needed before the status triggers (not a damage multiplier)
---@field buffs integer[] # its resident SpEffects (SpEffectParam rows): mostly buffs, some passive behaviours (regen, immunities)

---The boss's stats from its NpcParam row, live; `{ default = true }` gives them as they were before the first set_stat.
